 const { useState, useRef } = React;

 function ContactForm() {
     const [errors, setErrors] = useState({ name: '', email: '' });
     const formRef = useRef(null);

     const handleSubmit = (e) => {
         e.preventDefault();

         const form = e.target;
         const newErrors = { name: '', email: '' };
         let isValid = true;
         let firstInvalidField = null;

         if (!form.name.value.trim()) {
             newErrors.name = "Error: Name is required.";
             isValid = false;
             if (!firstInvalidField) firstInvalidField = form.name;
         }

         // Basic email check in addition to browser validation
         if (!form.email.value.trim() || !form.email.validity.valid) {
             newErrors.email = "Error: Please enter a valid email address.";
             isValid = false;
             if (!firstInvalidField) firstInvalidField = form.email;
         }

         setErrors(newErrors);

         if (!isValid && firstInvalidField) {
             // Give React a tick to render the error messages to the DOM
             // so aria-describedby connects properly before focus
             setTimeout(() => firstInvalidField.focus(), 0);
         } else if (isValid) {
             alert("Form submitted successfully!");
             form.reset();
             setErrors({ name: '', email: '' });
         }
     };

     return (
         <main className="form-container">
             <h1>Contact Support</h1>
             <p className="required-legend"><span aria-hidden="true">*</span> indicates required field</p>
             <form onSubmit={handleSubmit} noValidate ref={formRef}>
                 <div className="form-field">
                     <label htmlFor="name">Full name <span aria-hidden="true">*</span></label>
                     <input 
                         id="name" 
                         name="name" 
                         type="text" 
                         required 
                         autoComplete="name"
                         aria-invalid={errors.name ? "true" : undefined}
                         aria-describedby={errors.name ? "name-error" : undefined}
                     />
                     {errors.name && <p id="name-error" className="error-text">{errors.name}</p>}
                 </div>

                 <div className="form-field">
                     <label htmlFor="email">Email address <span aria-hidden="true">*</span></label>
                     <input 
                         id="email" 
                         name="email" 
                         type="email" 
                         required 
                         autoComplete="email"
                         aria-invalid={errors.email ? "true" : undefined}
                         aria-describedby={errors.email ? "email-error" : undefined}
                     />
                     {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
                 </div>

                 <div className="form-field">
                     <label htmlFor="phone">Phone number (optional)</label>
                     <input 
                         id="phone" 
                         name="phone" 
                         type="tel" 
                         autoComplete="tel"
                         aria-describedby="phone-help"
                     />
                     <p id="phone-help" className="help-text">Expected format: +1 (555) 123-4567</p>
                 </div>

                 <button type="submit">Submit Request</button>
             </form>
         </main>
     );
 }

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ContactForm />);

