', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-dark--validation-message-absent/google/gemini-3.1-pro-preview__s0/styles.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='/* Base styles */
body {
    margin: 0;
    padding: 2rem;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: #121212;
    color: #e0e0e0;
    display: flex;
    justify-content: center;
}

main {
    width: 100%;
    max-width: 480px;
    background-color: #1e1e1e;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

h1 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #ffffff;
}

/* Form Layout */
form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* Typography and colors */
label {
    font-weight: 500;
    font-size: 0.95rem;
    color: #e0e0e0;
}

.required-marker {
    color: #ff5252;
    margin-left: 0.25rem;
}

.help-text {
    font-size: 0.85rem;
    color: #a0a0a0;
    margin: 0;
}

.error-text {
    font-size: 0.875rem;
    color: #ff9999;
    margin-top: 0.25rem;
    margin-bottom: 0;
}

/* Inputs */
input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 0.75rem;
    border-radius: 4px;
    border: 1px solid #333;
    background-color: #2c2c2c;
    color: #ffffff;
    font-size: 1rem;
    transition: border-color 0.2s, box-shadow 0.2s;
}

/* Interactive states */
input:focus {
    outline: none;
    border-color: #bb86fc;
    box-shadow: 0 0 0 2px rgba(187, 134, 252, 0.3);
}

input[aria-invalid="true"] {
    border-color: #ff9999;
}

input:invalid:not(:focus):not(:placeholder-shown) {
    /* Optional: style invalid state if desired later, 
       but keeping simple for now as requested no inline validation messages on initial render */
}

/* Button */
button[type="submit"] {
    margin-top: 1rem;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 4px;
    background-color: #bb86fc;
    color: #000000;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
}

button[type="submit"]:hover {
    background-color: #9965f4;
}

button[type="submit"]:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(187, 134, 252, 0.5);
}

button[type="submit"]:active {
    background-color: #7b4ec2;
}

/* Accessibility: High contrast fallback */
@media (prefers-contrast: high) {
    body {
        background-color: black;
        color: white;
    }
    main {
        border: 1px solid white;
    }
    input {
        border: 2px solid white;
    }
    button[type="submit"] {
        background-color: white;
        color: black;
        border: 2px solid white;
    }
}
